import { test, expect } from '@playwright/test';

test.describe('Login Form Validation', () => {
  test('should not submit the form with empty fields', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/login');
    await page.click('a#login-button');
    await expect(page.locator('input[name="user_name"]')).toBeVisible();
    await expect(page.locator('input[name="password"]')).toBeVisible();
    await expect(page.locator('div#error')).toBeVisible();
    await expect(page.locator('div#error')).toHaveTextContaining('Username is required');
  });

  test('should submit the form with valid username and empty password', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/login');
    await page.click('a#login-button');
    await page.fill('input[name="user_name"]', 'standard_user');
    await page.fill('input[name="password"]');
    await expect(page.locator('div#error')).toBeVisible();
    await expect(page.locator('div#error')).toHaveTextContaining('Password is required');
  });
});
